import { Component, OnInit } from '@angular/core';
import { JobService } from '../../../core/services/job.service';
import { AuthService } from '../../../core/services/auth.service';
import { ToastService } from '../../../core/services/toast.service';
import { Job } from '../../../core/models/job.model';
import { User } from '../../../core/models/user.model';

@Component({
  selector: 'app-manage-jobs',
  templateUrl: './manage-jobs.component.html',
  styleUrls: ['./manage-jobs.component.css']
})
export class ManageJobsComponent implements OnInit {
  jobs: Job[] = [];
  isLoading = true;
  hasError = false;
  currentUser: User | null = null;

  // Delete modal state
  isDeleteModalOpen = false;
  jobToDelete: Job | null = null;
  isDeleting = false;

  constructor(
    private jobService: JobService,
    private authService: AuthService,
    private toast: ToastService
  ) {}

  ngOnInit(): void {
    this.currentUser = this.authService.currentUserValue;
    this.fetchMyJobs();
  }

  fetchMyJobs(): void {
    this.isLoading = true;
    this.hasError = false;

    this.jobService.getAllJobs({ limit: 100 }).subscribe({
      next: (res) => {
        const allJobs = res.data || [];
        const currentUserId = this.currentUser?._id || this.currentUser?.id;

        if (this.currentUser?.role === 'admin') {
          // Admin can see and manage all jobs
          this.jobs = allJobs;
        } else {
          // Employer sees only their own jobs
          this.jobs = allJobs.filter(job => {
            const empId = typeof job.employer === 'object' ? job.employer?._id : job.employer;
            return empId === currentUserId;
          });
        }
        this.isLoading = false;
      },
      error: () => {
        this.hasError = true;
        this.isLoading = false;
      }
    });
  }

  promptDeleteJob(job: Job): void {
    this.jobToDelete = job;
    this.isDeleteModalOpen = true;
  }

  cancelDelete(): void {
    this.isDeleteModalOpen = false;
    this.jobToDelete = null;
  }

  confirmDelete(): void {
    if (!this.jobToDelete) return;

    const id = this.jobToDelete._id || this.jobToDelete.id;
    if (!id) return;

    this.isDeleting = true;

    this.jobService.deleteJob(id).subscribe({
      next: () => {
        this.isDeleting = false;
        this.isDeleteModalOpen = false;
        this.toast.success('Job Deleted', 'The job posting has been permanently removed.');
        this.jobs = this.jobs.filter(j => (j._id || j.id) !== id);
        this.jobToDelete = null;
      },
      error: (err) => {
        this.isDeleting = false;
        this.toast.error('Deletion Failed', err.error?.message || 'Could not delete job.');
      }
    });
  }
}
<div class="manage-jobs-page container section-padding">
  <div class="page-header d-flex justify-content-between align-items-center mb-4 flex-wrap gap-3">
    <div>
      <h1 class="page-title">Manage Job Postings</h1>
      <p class="page-subtitle">Track, update, or remove active job listings and review candidate applications.</p>
    </div>
    <a routerLink="/jobs/create" class="btn btn-primary">
      <i class="fa-solid fa-plus"></i> Post a New Job
    </a>
  </div>

  <!-- Loading State -->
  <app-loading-spinner *ngIf="isLoading" message="Loading your job postings..."></app-loading-spinner>

  <!-- Error Alert -->
  <div class="alert alert-danger" *ngIf="hasError && !isLoading">
    <i class="fa-solid fa-circle-exclamation"></i>
    <div>Failed to load jobs. <button class="btn btn-sm btn-outline-danger" (click)="fetchMyJobs()">Retry</button></div>
  </div>

  <!-- Empty State -->
  <app-empty-state
    *ngIf="!isLoading && !hasError && jobs.length === 0"
    icon="fa-solid fa-briefcase"
    title="No Active Job Listings"
    message="You haven't posted any job openings yet. Create your first opening to attract candidates."
    actionText="Post a Job Opening"
    actionRoute="/jobs/create">
  </app-empty-state>

  <!-- Jobs Table / Card List -->
  <div class="card overflow-hidden" *ngIf="!isLoading && !hasError && jobs.length > 0">
    <div class="table-responsive">
      <table class="data-table">
        <thead>
          <tr>
            <th>Job Role & Title</th>
            <th>Type</th>
            <th>Location</th>
            <th>Salary</th>
            <th>Created</th>
            <th class="text-right">Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let job of jobs">
            <td>
              <div class="job-table-title-cell">
                <a [routerLink]="['/jobs', job._id || job.id]" class="job-table-title">
                  {{ job.title }}
                </a>
                <span class="job-table-company">{{ job.companyName }}</span>
              </div>
            </td>
            <td>
              <span class="badge badge-primary">{{ job.type }}</span>
            </td>
            <td>
              <span class="text-muted"><i class="fa-solid fa-location-dot"></i> {{ job.location }}</span>
            </td>
            <td>
              <span class="font-semibold">{{ job.salary ? ('$' + job.salary.toLocaleString()) : 'Negotiable' }}</span>
            </td>
            <td>
              <span class="text-muted text-sm">{{ job.createdAt | date:'mediumDate' }}</span>
            </td>
            <td>
              <div class="table-actions-row">
                <a
                  [routerLink]="['/jobs', job._id || job.id, 'applications']"
                  class="btn btn-sm btn-primary"
                  title="View Candidate Applications">
                  <i class="fa-solid fa-users"></i> Applicants
                </a>
                <a
                  [routerLink]="['/jobs', job._id || job.id, 'edit']"
                  class="btn btn-sm btn-secondary"
                  title="Edit Job">
                  <i class="fa-regular fa-pen-to-square"></i>
                </a>
                <button
                  type="button"
                  class="btn btn-sm btn-outline-danger"
                  (click)="promptDeleteJob(job)"
                  title="Delete Job">
                  <i class="fa-regular fa-trash-can"></i>
                </button>
              </div>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- Confirm Delete Modal -->
<app-confirm-modal
  [isOpen]="isDeleteModalOpen"
  title="Delete Job Listing"
  [message]="'Are you sure you want to delete \'' + (jobToDelete?.title || 'this job') + '\'? All associated applicant records will also be removed.'"
  confirmText="Delete Job"
  cancelText="Keep Job"
  [isDanger]="true"
  [isLoading]="isDeleting"
  (confirm)="confirmDelete()"
  (cancel)="cancelDelete()">
</app-confirm-modal>
